// @@ AI-COMMENT: TechStack page component redesigned with Neo-Brutalist industrial grid
import React, { useState } from "react";
import TechCard from "../../components/TechCard/TechCard";
import SkillEvidenceModal from "../../components/PortfolioInteractions/SkillEvidenceModal";
import interactionStyles from "../../components/PortfolioInteractions/Interactions.module.css";
import usePortfolioData from "../../hooks/usePortfolioData";
import styles from "./TechStack.module.css";

const TechStack = ({ onExplore }) => {
  const [selectedSkill, setSelectedSkill] = useState(null);
  const { techStack: techCategories, experience, projects, loading } = usePortfolioData();

  if (loading) return null;

  return (
    <div className={`${styles.container} ${interactionStyles.scope}`}>
      {/* ── Neubrutalist Page Header ── */}
      <div className={styles.headerContainer}>
        <h1 className={styles.headerTitle}>Technology Stack</h1>
      </div>

      <p className={interactionStyles.pageIntro}>Explore my skills through company contributions and case studies. Select any tile to see the work behind it.</p>
      {/* ── Main Content Area ── */}
      <div className={styles.mainContent}>
        {techCategories.map((category, categoryIndex) => (
          <section key={categoryIndex} className={styles.categorySection}>
            <h2 className={styles.categoryTitle}>{category.category}</h2>
            <div className={styles.techGrid}>
              {category.technologies.map((tech, techIndex) => (
                <div key={techIndex} className={styles.techItem}>
                  <TechCard
                    name={tech.name}
                    icon={tech.icon}
                    label={tech.label}
                    projectCount={tech.projectCount}
                    selected={selectedSkill?.name === tech.name}
                    onClick={() => setSelectedSkill(tech)}
                  />
                </div>
              ))}
            </div>
          </section>
        ))}
      </div>
      <SkillEvidenceModal skill={selectedSkill} experience={experience} projects={projects} onHide={() => setSelectedSkill(null)} onExplore={(page, selection) => { setSelectedSkill(null); onExplore(page, selection); }} />
    </div>
  );
};

export default TechStack;
