import React from 'react';
import { Modal } from 'react-bootstrap';
import { FiArrowRight, FiBriefcase } from 'react-icons/fi';
import { getSkillEvidence } from '../../utils/portfolioEvidence';
import styles from './Interactions.module.css';

export default function SkillEvidenceModal({ skill, experience, projects, onHide, onExplore }) {
  const evidence = skill ? getSkillEvidence(skill, experience, projects) : { companies: [], projects: [] };
  return (
    <Modal show={Boolean(skill)} onHide={onHide} centered scrollable size="lg" contentClassName={`${styles.scope} ${styles.modalContent}`} aria-labelledby="skill-evidence-title">
      <Modal.Header closeButton className={styles.modalHeader}>
        <div><p className={styles.eyebrow}>Technology → projects → contributions</p><Modal.Title id="skill-evidence-title">{skill?.name}{evidence.projects.length > 0 ? ' across projects' : ''}</Modal.Title></div>
      </Modal.Header>
      <Modal.Body className={styles.modalBody}>
        <p className={styles.skillSource}>{skill?.label || skill?.name}</p>
        {evidence.companies.length > 0 ? <section><h3>Where I used it</h3>{evidence.companies.map(job => <article key={job.id} className={styles.evidenceCompany}>
          <div className={styles.evidenceHeading}><div><h4><FiBriefcase aria-hidden="true" /> {job.organization}</h4><p>{job.title} · {job.duration}</p></div><button onClick={() => onExplore('experience', { companyId: job.id, contributionIndex: job.contributions[0]?.index ?? 0 })}>View company <FiArrowRight aria-hidden="true" /></button></div>
          {job.contributions.length > 0 && <ul>{job.contributions.map(item => <li key={item.index}>{item.description}</li>)}</ul>}
        </article>)}</section> : null}
        {evidence.projects.length > 0 ? <section><h3>{evidence.projects.length} {evidence.projects.length === 1 ? 'project' : 'projects'}</h3><div className={styles.evidenceProjects}>{evidence.projects.map(project => <button key={project.id} onClick={() => onExplore('projects', { projectId: project.id })}><span><small>{project.company}</small><strong>{project.title}</strong>{project.outcomes?.[0] && <em>{project.outcomes[0]}</em>}</span><FiArrowRight aria-hidden="true" /></button>)}</div></section> : <div className={styles.noEvidence}><h3>Part of my toolkit</h3><p>A project example for this skill hasn’t been added yet.</p></div>}
        <button className={styles.textAction} onClick={() => onExplore('projects', evidence.projects.length > 0 ? { technology: skill?.name || '' } : {})}>{evidence.projects.length > 0 ? `Explore projects for ${skill?.name}` : 'Explore all projects'} <FiArrowRight aria-hidden="true" /></button>
      </Modal.Body>
    </Modal>
  );
}
